UPDATE public.site_pages SET content = '<h2>Our Story</h2><p>Veloura Essence was born from a passion for refined, long-lasting fragrance — designed for the modern Bangladeshi.</p><h2>Our Promise</h2><p>Every bottle is crafted with premium ingredients, honest pricing, and an experience worthy of every occasion.</p><h2>Our Mission</h2><p>To redefine luxury fragrance in Bangladesh, one signature scent at a time.</p>' WHERE slug = 'about';

UPDATE public.site_pages SET content = '<h2>1. Information We Collect</h2><p>We collect information you provide when placing an order or contacting support, including name, phone number, delivery address, email (optional), and order history.</p><h2>2. How We Use Your Information</h2><p>Your information is used to process orders, coordinate delivery, provide customer support, and improve our products and services.</p><h2>3. Sharing &amp; Disclosure</h2><p>We never sell your personal information. Limited information is shared with delivery partners and payment processors strictly to fulfill your order.</p><h2>4. Data Security</h2><p>We use industry-standard safeguards to protect your information.</p><h2>5. Your Rights</h2><p>You may request access to, correction of, or deletion of your personal data at any time by contacting us.</p><h2>6. Contact</h2><p>For privacy-related questions, reach us via the contact details in our footer.</p>' WHERE slug = 'privacy';

UPDATE public.site_pages SET content = '<h2>Shipping</h2><ul><li>Nationwide delivery across Bangladesh</li><li>Estimated delivery: 2–4 business days</li><li>Free shipping on orders above ৳999</li><li>Standard delivery charge: ৳60 inside Dhaka, ৳120 outside Dhaka</li></ul><h2>Returns</h2><ul><li>Unopened products: 7-day return/exchange window</li><li>Opened fragrances: not eligible for return (hygiene reasons)</li><li>Refunds are processed within 5–7 business days after the returned item is received</li></ul><h2>Damaged or Wrong Items</h2><p>If you receive a damaged or wrong item, contact us within 48 hours of delivery with photos.</p>' WHERE slug = 'shipping';

UPDATE public.site_pages SET content = '<h2>1. Acceptance of Terms</h2><p>By accessing or shopping at Veloura Essence, you agree to be bound by these Terms &amp; Conditions and our Privacy Policy.</p><h2>2. Orders &amp; Payment</h2><p>All orders are subject to product availability and confirmation of payment. We accept Cash on Delivery and supported digital payment methods at checkout.</p><ul><li>Prices are listed in Bangladeshi Taka (৳).</li><li>We reserve the right to refuse or cancel any order.</li><li>Promotional codes cannot be combined unless specified.</li></ul><h2>3. Shipping &amp; Delivery</h2><p>We deliver nationwide across Bangladesh. Estimated delivery is 2–4 business days. Free shipping on orders above ৳999.</p><h2>4. Returns &amp; Exchanges</h2><p>Unopened products can be returned or exchanged within 7 days of delivery. Opened fragrances are not eligible for return for hygiene reasons.</p><h2>5. Intellectual Property</h2><p>All content on this site — including product names, imagery, and branding — is the property of Veloura Essence and may not be reproduced without permission.</p><h2>6. Contact</h2><p>For questions about these terms, reach us via the contact details on our footer.</p>' WHERE slug = 'terms';